/* From Uiverse.io by vinodjangid07  - Tags: material design, gradient, card, input, payment, mastercard, visa, credit card */
.__UIV_SCOPE__ .visa-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  width: 300px;
  height: 180px;
  background-image: radial-gradient(
    circle 897px at 9% 80.3%,
    rgba(55, 60, 245, 1) 0%,
    rgba(234, 161, 15, 0.9) 100.2%
  );
  border-radius: 10px;
  padding: 20px;
  font-family: Arial, Helvetica, sans-serif;
  position: relative;
  gap: 15px;
}
.__UIV_SCOPE__ .logoContainer {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: fit-content;
  position: absolute;
  top: 0;
  left: 0;
  padding: 18px;
}
.__UIV_SCOPE__ .svgLogo {
  height: 40px;
  width: auto;
}
.__UIV_SCOPE__ .inputstyle::placeholder {
  color: #ffffff;
}
.__UIV_SCOPE__ .inputstyle {
  background-color: transparent;
  border: none;
  outline: none;
  color: white;
  caret-color: red;
  font-size: 13px;
  height: 25px;
  letter-spacing: 1.5px;
}
.__UIV_SCOPE__ .number-container {
  width: 100%;
  height: fit-content;
  display: flex;
  flex-direction: column;
}
.__UIV_SCOPE__ #cardNumber {
  width: 100%;
  height: 25px;
}
.__UIV_SCOPE__ .name-date-cvv-container {
  width: 100%;
  height: 25px;
  display: flex;
  gap: 10px;
}
.__UIV_SCOPE__ .name-wrapper {
  width: 60%;
  height: fit-content;
  display: flex;
  flex-direction: column;
}
.__UIV_SCOPE__ .expiry-wrapper,
.__UIV_SCOPE__ .cvv-wrapper {
  width: 30%;
  height: fit-content;
  display: flex;
  flex-direction: column;
}
.__UIV_SCOPE__ .cvv-wrapper {
  width: 10%;
}
.__UIV_SCOPE__ #expiry,
.__UIV_SCOPE__ #cvv {
  width: 100%;
}
.__UIV_SCOPE__ .input-label {
  font-size: 8px;
  letter-spacing: 1.5px;
  color: #e2e2e2;
  width: 100%;
}
